css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; }
.loader .blade { position: relative; width: 88%; height: 88%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 22%, var(--accent-2)) 0 57%, transparent 58%), repeating-conic-gradient(from 0deg, var(--accent) 0 7deg, transparent 7deg 18deg); animation: saw calc(var(--loader-speed) * .7) linear infinite; }
.loader .blade::after { content: ''; position: absolute; inset: 40%; border-radius: 50%; background: #f8fafc; box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 24%, var(--accent-2)); }
.loader span { position: absolute; bottom: 13%; right: 7%; width: 9%; height: 3%; border-radius: 999px; background: var(--accent); animation: spark calc(var(--loader-speed) * 1.1) ease-out infinite; }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .55); }
@keyframes saw { to { transform: rotate(360deg); } }
@keyframes spark { 0% { opacity: 0; transform: translate(0, 0) scaleX(.4); } 22% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size) * .24), calc(var(--loader-size) * .1)) scaleX(1.7); } }
